BEGIN;

CREATE TABLE IF NOT EXISTS interactions_archive (LIKE interactions INCLUDING ALL);

INSERT INTO interactions_archive
SELECT i.*
FROM interactions i
JOIN fans f ON i.interact_fan_pivot = f.user_registry
JOIN membershipandspending m ON f.user_registry = m.member_fan_pivot
WHERE f.status_tag = 'Inactive'
  AND m.memb_kind = 'Basic'
  AND i.time_mark < CURRENT_DATE - INTERVAL '3 years';

DELETE FROM interactions
WHERE activity_reg IN (
    SELECT i.activity_reg
    FROM interactions i
    JOIN fans f ON i.interact_fan_pivot = f.user_registry
    JOIN membershipandspending m ON f.user_registry = m.member_fan_pivot
    WHERE f.status_tag = 'Inactive'
      AND m.memb_kind = 'Basic'
      AND i.time_mark < CURRENT_DATE - INTERVAL '3 years'
);

COMMIT;

SELECT COUNT(*) AS archive_record_count FROM interactions_archive;
